from pathlib import Path
root=Path('/home/ubuntu/nox-offline-player')
(root/'capacitor.config.ts').write_text('''import type { CapacitorConfig } from "@capacitor/cli";\n\nconst config: CapacitorConfig = {\n  appId: "com.nox.offlineplayer",\n  appName: "NOX Offline Player",\n  webDir: "dist/public",\n  bundledWebRuntime: false,\n  server: { cleartext: false },\n};\n\nexport default config;\n''')
workflow=root/'.github/workflows/android.yml'
workflow.parent.mkdir(parents=True, exist_ok=True)
workflow.write_text('''name: Android APK\n\non:\n  workflow_dispatch:\n  push:\n    branches: [main, stage3-website-apk]\n\njobs:\n  build-apk:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: read\n    steps:\n      - uses: actions/checkout@v4\n      - uses: pnpm/action-setup@v4\n        with:\n          version: 10\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n          cache: pnpm\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: 21\n      - uses: android-actions/setup-android@v3\n      - name: Install dependencies\n        run: pnpm install --frozen-lockfile\n      - name: Build web bundle\n        run: pnpm build\n      - name: Create Android project\n        run: pnpm exec cap add android\n      - name: Copy web bundle\n        run: pnpm exec cap copy android\n      - name: Add Android media permissions\n        run: node scripts/prepare-android-manifest.mjs\n      - name: Assemble debug APK\n        run: cd android && ./gradlew assembleDebug --no-daemon\n      - name: Upload debug APK\n        uses: actions/upload-artifact@v4\n        with:\n          name: nox-debug-apk\n          path: android/app/build/outputs/apk/debug/app-debug.apk\n''')
